#@ ImagePlus imp
#@ Double(label="Gaussian Sigma", min=1, max=10, value=2) sigma
#@output ImagePlus result

import ij.IJ

// imp is the connected image, not an active Fiji window.
// FlowGraph converts Pillow pixels to an owned ImagePlus.
// RGB channels are handled by ImageJ; no axis loop is needed.
IJ.run(imp, "Gaussian Blur...", "sigma=" + sigma)

// This writes to the ImageJ log; it does not create a viewer.
IJ.log("Successfully applied Gaussian Blur with a sigma of: " + sigma)

// Publish the processed image on the result output port.
result = imp
